/* ---------- drawing helpers for this lesson (prefixed MN_ so they never clash with engine globals) ---------- */
const MN_F='font-family="Nunito Sans, sans-serif"';
const MN_INK='#18213A', MN_MUT='#5C6577', MN_AX='#ADB5BD';
const MN_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${MN_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||MN_INK}"${o.it?' font-style="italic"':''}>${t}</text>`;
const MN_L=(x1,y1,x2,y2,col=MN_INK,w=3,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const MN_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.dash?` stroke-dasharray="${o.dash}"`:''}/>`;
const MN_dash=(x,y,w,h,col)=>MN_box(x,y,w,h,{fill:'none',st:col,sw:3,dash:'9 7',r:16});
const MN_poly=(P,col,w=3)=>`<polyline points="${P.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"/>`;
const MN_arrow=(x1,y1,x2,y2,col=MN_INK,w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return MN_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const MN_sub=(a,b)=>`${a}<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
const MN_dot=(x,y,col=MN_INK,r=7)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${col}"/>`;
/* resistor zigzag, horizontal (x1..x2 at y) or vertical (x at y1..y2); half-length hl of the zigzag */
const MN_res=(x1,x2,y,col=MN_INK,w=3,hl=36)=>{const m=(x1+x2)/2,a=m-hl,s=2*hl/6;let p=[[x1,y],[a,y]];for(let i=0;i<6;i++)p.push([a+s*(i+.5),y+(i%2?11:-11)]);p.push([m+hl,y],[x2,y]);return MN_poly(p,col,w)};
const MN_resV=(x,y1,y2,col=MN_INK,w=3,hl=36)=>{const m=(y1+y2)/2,a=m-hl,s=2*hl/6;let p=[[x,y1],[x,a]];for(let i=0;i<6;i++)p.push([x+(i%2?11:-11),a+s*(i+.5)]);p.push([x,m+hl],[x,y2]);return MN_poly(p,col,w)};
/* sources: voltage (+ on top), voltage horizontal (+ on the right), current (arrow up), dependent current (diamond, arrow up) */
const MN_vs=(cx,cy,r=28,col=ORG)=>`<circle cx="${cx}" cy="${cy}" r="${r}" fill="#FFFFFF" stroke="${col}" stroke-width="4"/>`+MN_T(cx,cy-r*.18,'+',{fs:r*.9,fw:800,a:'middle',fill:col})+MN_T(cx,cy+r*.72,'−',{fs:r*.9,fw:800,a:'middle',fill:col});
const MN_vsH=(cx,cy,r=28,col=ORG)=>`<circle cx="${cx}" cy="${cy}" r="${r}" fill="#FFFFFF" stroke="${col}" stroke-width="4"/>`+MN_T(cx-r*.42,cy+r*.3,'−',{fs:r*.9,fw:800,a:'middle',fill:col})+MN_T(cx+r*.42,cy+r*.3,'+',{fs:r*.9,fw:800,a:'middle',fill:col});
const MN_is=(cx,cy,r=28,col=ORG)=>`<circle cx="${cx}" cy="${cy}" r="${r}" fill="#FFFFFF" stroke="${col}" stroke-width="4"/>`+MN_arrow(cx,cy+r*.6,cx,cy-r*.62,col,4);
const MN_dia=(cx,cy,r=30,col=GRN)=>`<polygon points="${cx},${cy-r} ${cx+r},${cy} ${cx},${cy+r} ${cx-r},${cy}" fill="#FFFFFF" stroke="${col}" stroke-width="4" stroke-linejoin="round"/>`+MN_arrow(cx,cy+r*.5,cx,cy-r*.52,col,4);
/* ground symbol hanging below (x,y) */
const MN_gnd=(x,y,col=MN_INK)=>MN_L(x,y,x,y+16,col,3)+MN_L(x-20,y+16,x+20,y+16,col,3)+MN_L(x-12,y+24,x+12,y+24,col,3)+MN_L(x-5,y+32,x+5,y+32,col,3);
/* a clockwise mesh-current arc round (cx,cy) with its arrowhead */
const MN_cw=(cx,cy,r,col,w=4)=>{const d=Math.PI/180,a0=120*d,a1=410*d;const x0=cx+r*Math.cos(a0),y0=cy+r*Math.sin(a0),x1=cx+r*Math.cos(a1),y1=cy+r*Math.sin(a1);const tx=-Math.sin(a1),ty=Math.cos(a1),nx=Math.cos(a1),ny=Math.sin(a1),h=13;
  return `<path d="M${x0.toFixed(1)},${y0.toFixed(1)} A${r},${r} 0 1 1 ${x1.toFixed(1)},${y1.toFixed(1)}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round"/>`+`<polygon points="${(x1+tx*h).toFixed(1)},${(y1+ty*h).toFixed(1)} ${(x1+nx*h*.55).toFixed(1)},${(y1+ny*h*.55).toFixed(1)} ${(x1-nx*h*.55).toFixed(1)},${(y1-ny*h*.55).toFixed(1)}" fill="${col}"/>`};
/* a two-window circuit outline: outer rectangle and a shared middle branch */
const MN_win=(x1,y1,x2,y2,xm,col=MN_INK,w=3)=>MN_L(x1,y1,x2,y1,col,w)+MN_L(x1,y2,x2,y2,col,w)+MN_L(x1,y1,x1,y2,col,w)+MN_L(x2,y1,x2,y2,col,w);
/* a 2 × 2 matrix drawn with brackets: rows of [text, colour] */
const MN_mat=(x,y,rows,fs=34,cw=110,rh=52)=>{const w=cw*2,h=rh*2;let s=MN_L(x,y-fs,x,y-fs+h+8,MN_INK,3)+MN_L(x,y-fs,x+12,y-fs,MN_INK,3)+MN_L(x,y-fs+h+8,x+12,y-fs+h+8,MN_INK,3)+MN_L(x+w,y-fs,x+w,y-fs+h+8,MN_INK,3)+MN_L(x+w,y-fs,x+w-12,y-fs,MN_INK,3)+MN_L(x+w,y-fs+h+8,x+w-12,y-fs+h+8,MN_INK,3);
  rows.forEach((r,i)=>r.forEach(([t,c],j)=>{s+=MN_T(x+cw*(j+.5),y+rh*i,t,{fs,fw:800,a:'middle',fill:c||MN_INK})}));return s};
/* the ladder of the hook: 7 branches, 5 nodes (design size 760 × 320, drawn at half size) */
const MN_ladder=(col)=>{const X=[80,280,480,680],T=80,B=260;let s='';s+=MN_L(80,B,680,B,col,5);
  s+=MN_L(80,T,80,B,col,5);s+=MN_vs(80,170,34,ORG);
  [280,480,680].forEach(x=>{s+=MN_resV(x,T,B,col,5,40)});
  [[80,280],[280,480],[480,680]].forEach(([a,b])=>{s+=MN_res(a,b,T,col,5,40)});return s};

