function EXTRA(R,ICON){
 /* hook: the same ladder twice, branch by branch (seven unknown currents) and node by node */
 ICON.mnPile=(x,y)=>`<g transform="translate(${x-190} ${y-110})">${MN_box(0,0,380,220,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${MN_T(20,34,'branch by branch: 7 unknowns',{fs:22,fw:800,fill:ORG})}<g transform="translate(0 46) scale(.5)">${MN_ladder(MN_INK)}${[[180,140],[380,140],[580,140],[322,190],[522,190],[722,190],[22,190]].map(([a,bb])=>MN_T(a,bb,'?',{fs:54,fw:800,a:'middle',fill:ORG})).join('')}</g></g>`;
 ICON.mnNodes=(x,y)=>`<g transform="translate(${x-190} ${y-110})">${MN_box(0,0,380,220,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${MN_T(20,34,'or: one voltage per node',{fs:22,fw:800,fill:BLU})}<g transform="translate(0 46) scale(.5)">${MN_ladder(MN_INK)}${[80,280,480,680].map((xx,i)=>MN_dot(xx,80,BLU,13)+MN_T(xx+(i?0:52),46,'v'+'₁₂₃₄'[i],{fs:44,fw:800,a:'middle',fill:BLU})).join('')}${MN_T(380,316,'0 V',{fs:40,fw:800,a:'middle',fill:BLU})}</g></g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.mnMesh=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${MN_win(20,40,400,300,210,MN_INK,5)}${MN_L(210,40,210,300,MN_INK,5)}${MN_cw(115,170,62,BLU,6)}${MN_T(115,184,'i₁',{fs:42,fw:800,a:'middle',fill:BLU})}${MN_cw(305,170,62,BLU,6)}${MN_T(305,184,'i₂',{fs:42,fw:800,a:'middle',fill:BLU})}</g>`;
 ICON.mnNode=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${MN_L(30,250,390,250,MN_INK,5)}${MN_L(60,90,60,250,MN_INK,5)}${MN_L(360,90,360,250,MN_INK,5)}${MN_L(60,90,360,90,MN_INK,5)}${MN_resV(210,90,250,MN_INK,5,44)}${MN_dot(60,90,ORG,14)}${MN_dot(360,90,ORG,14)}${MN_T(60,58,'v₁',{fs:42,fw:800,a:'middle',fill:ORG})}${MN_T(360,58,'v₂',{fs:42,fw:800,a:'middle',fill:ORG})}${MN_gnd(110,250)}${MN_T(150,300,'0 V',{fs:34,fw:800,fill:ORG})}</g>`;
 ICON.mnSuper=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${MN_L(50,160,150,160,MN_INK,6)}${MN_L(270,160,370,160,MN_INK,6)}${MN_vsH(210,160,58,GRN)}${MN_dot(50,160,GRN,16)}${MN_dot(370,160,GRN,16)}${MN_L(50,160,50,330,MN_INK,5)}${MN_L(370,160,370,330,MN_INK,5)}${MN_dash(0,70,420,180,GRN)}${MN_T(210,48,'one boundary',{fs:38,fw:800,a:'middle',fill:GRN})}${MN_T(210,300,'1 KCL + 1 constraint',{fs:30,fw:800,a:'middle',fill:GRN})}</g>`;
}
